import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { useAuth } from '../../context/AuthContext';
import { Shield, Lock, User, Eye, EyeOff, AlertTriangle } from 'lucide-react';

const LoginPage = () => {
  const [form, setForm] = useState({ username: '', password: '', role: 'USER' });
  const [showPw, setShowPw] = useState(false);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const { login } = useAuth();
  const navigate = useNavigate();

  const handleSubmit = async (e) => {
    e.preventDefault();
    setLoading(true);
    setError('');
    try {
      const data = await login(form.username, form.password, form.role);
      if (data.role === 'ADMIN') navigate('/admin/dashboard');
      else navigate('/user/dashboard');
    } catch (err) {
      const msg = err.response?.data?.error || 'Login failed';
      if (err.response?.data?.blocked) {
        navigate('/blocked');
      } else {
        setError(msg);
      }
    } finally {
      setLoading(false);
    }
  };

  return (
    <div style={styles.page}>
      {/* Animated background grid */}
      <div style={styles.grid} />

      <div style={styles.container}>
        {/* Logo */}
        <div style={styles.logoArea}>
          <div style={styles.shieldWrap}>
            <Shield size={40} color="#00d4ff" strokeWidth={1.5} />
          </div>
          <div>
            <h1 style={styles.title}>ZeroTrust</h1>
            <p style={styles.subtitle}>AI-Powered API Security Platform</p>
          </div>
        </div>

        {/* Role Selector */}
        <div style={styles.roleSection}>
          <p style={styles.roleLabel}>Access Level</p>
          <div style={styles.roleTabs}>
            {['USER', 'ADMIN'].map(r => (
              <button
                key={r}
                onClick={() => setForm(f => ({ ...f, role: r }))}
                style={{
                  ...styles.roleTab,
                  ...(form.role === r ? styles.roleTabActive : {})
                }}
              >
                {r === 'ADMIN' ? <Lock size={14} /> : <User size={14} />}
                <span>{r === 'ADMIN' ? 'Admin' : 'User'}</span>
              </button>
            ))}
          </div>
        </div>

        {/* Form */}
        <form onSubmit={handleSubmit} style={styles.form}>
          <div style={styles.fieldGroup}>
            <label style={styles.label}>Username</label>
            <div style={styles.inputWrap}>
              <User size={16} color="#666" style={styles.inputIcon} />
              <input
                type="text"
                value={form.username}
                onChange={e => setForm(f => ({ ...f, username: e.target.value }))}
                placeholder="Enter username"
                required
                style={styles.input}
              />
            </div>
          </div>

          <div style={styles.fieldGroup}>
            <label style={styles.label}>Password</label>
            <div style={styles.inputWrap}>
              <Lock size={16} color="#666" style={styles.inputIcon} />
              <input
                type={showPw ? 'text' : 'password'}
                value={form.password}
                onChange={e => setForm(f => ({ ...f, password: e.target.value }))}
                placeholder="Enter password"
                required
                style={styles.input}
              />
              <button
                type="button"
                onClick={() => setShowPw(v => !v)}
                style={styles.eyeBtn}
              >
                {showPw ? <EyeOff size={16} color="#666" /> : <Eye size={16} color="#666" />}
              </button>
            </div>
          </div>

          {error && (
            <div style={styles.error}>
              <AlertTriangle size={15} />
              <span>{error}</span>
            </div>
          )}

          <button type="submit" disabled={loading} style={styles.submitBtn}>
            {loading ? (
              <span style={styles.spinner}>●</span>
            ) : (
              <>
                <Shield size={16} />
                Sign In as {form.role === 'ADMIN' ? 'Administrator' : 'User'}
              </>
            )}
          </button>
        </form>

        <div style={styles.hint}>
          <p style={styles.hintText}>Default credentials: admin / Admin@123 | testuser / User@123</p>
        </div>

        <div style={styles.badges}>
          {['JWT', 'Zero Trust', 'AI/ML', 'RBAC'].map(b => (
            <span key={b} style={styles.badge}>{b}</span>
          ))}
        </div>
      </div>
    </div>
  );
};

const styles = {
  page: {
    minHeight: '100vh',
    background: '#050a14',
    display: 'flex',
    alignItems: 'center',
    justifyContent: 'center',
    fontFamily: "'JetBrains Mono', 'Courier New', monospace",
    position: 'relative',
    overflow: 'hidden',
  },
  grid: {
    position: 'absolute',
    inset: 0,
    backgroundImage: `
      linear-gradient(rgba(0,212,255,0.05) 1px, transparent 1px),
      linear-gradient(90deg, rgba(0,212,255,0.05) 1px, transparent 1px)
    `,
    backgroundSize: '50px 50px',
    animation: 'gridMove 20s linear infinite',
  },
  container: {
    background: 'rgba(8, 16, 32, 0.95)',
    border: '1px solid rgba(0, 212, 255, 0.2)',
    borderRadius: '16px',
    padding: '40px',
    width: '420px',
    backdropFilter: 'blur(20px)',
    boxShadow: '0 0 60px rgba(0, 212, 255, 0.1), inset 0 1px 0 rgba(255,255,255,0.05)',
    position: 'relative',
    zIndex: 1,
  },
  logoArea: {
    display: 'flex',
    alignItems: 'center',
    gap: '16px',
    marginBottom: '32px',
  },
  shieldWrap: {
    background: 'rgba(0, 212, 255, 0.1)',
    border: '1px solid rgba(0, 212, 255, 0.3)',
    borderRadius: '12px',
    padding: '12px',
    display: 'flex',
  },
  title: {
    color: '#ffffff',
    fontSize: '24px',
    fontWeight: '700',
    margin: 0,
    letterSpacing: '0.05em',
  },
  subtitle: {
    color: '#00d4ff',
    fontSize: '11px',
    margin: '4px 0 0 0',
    letterSpacing: '0.1em',
    textTransform: 'uppercase',
  },
  roleSection: { marginBottom: '28px' },
  roleLabel: {
    color: '#8899aa',
    fontSize: '11px',
    letterSpacing: '0.1em',
    textTransform: 'uppercase',
    margin: '0 0 10px 0',
  },
  roleTabs: {
    display: 'flex',
    gap: '8px',
    background: 'rgba(0,0,0,0.4)',
    padding: '4px',
    borderRadius: '10px',
  },
  roleTab: {
    flex: 1,
    display: 'flex',
    alignItems: 'center',
    justifyContent: 'center',
    gap: '6px',
    padding: '10px',
    border: 'none',
    borderRadius: '7px',
    background: 'transparent',
    color: '#8899aa',
